<main id="conteudo" class="page-shell"><div class="page-heading"><p class="eyebrow">Sua seleção</p><h1>Carrinho</h1></div><?php if (!$items): ?><p class="empty-state">Seu carrinho está vazio. <a href="index.php?rota=catalogo">Ver catálogo</a></p><?php else: ?><div class="cart-list"><?php foreach ($items as $item): ?><article class="cart-item"><img src="<?= View::escape($item['imagem'] ?: 'assets/css/img/produto1.png') ?>" alt=""><div><h2><?= View::escape($item['nome']) ?></h2><p><?= (int) $item['quantidade'] ?> × R$ <?= number_format((float) $item['preco'], 2, ',', '.') ?></p></div><form method="post" action="index.php?rota=carrinho/remover"><input type="hidden" name="item_id" value="<?= (int) $item['id'] ?>"><button class="text-button">Remover</button></form></article><?php endforeach; ?></div><p class="cart-total">Total: <strong>R$ <?= number_format($total, 2, ',', '.') ?></strong></p><a class="button button-primary" href="pagamento.php">Finalizar pedido</a><?php endif; ?></main>
